import{_ as a,o as n,c as i,ag as e}from"./chunks/framework.PVHj0As1.js";const l="/pub-blog/assets/image-20250623200408525.C1g1AZX8.png",p="/pub-blog/assets/image-20250623204001620.DNNl1o3Y.png",t="/pub-blog/assets/PixPin_2025-06-23_21-08-37.d-IR8uqH.gif",h="/pub-blog/assets/image-20250623211938406.GMpvb40O.png",r="/pub-blog/assets/image-20250622200325374.BLr7GNE1.png",m=JSON.parse('{"title":"HarmonyOS 组件服用 @Reusable装饰器的基本使用","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS 组件复用 @Reusable装饰器的基本使用/HarmonyOS 组件复用 @Reusable装饰器的基本使用.md","filePath":"鸿蒙开发技巧/HarmonyOS 组件复用 @Reusable装饰器的基本使用/HarmonyOS 组件复用 @Reusable装饰器的基本使用.md","lastUpdated":1750695195000,"__rawMarkdown":"# HarmonyOS 组件服用 @Reusable装饰器的基本使用\\n\\n## 作用\\n\\n`@Reusable`装饰器标记的自定义组件支持视图节点、组件实例和状态上下文的复用，避免重复创建和销毁，提升性能。\\n\\n## 原理\\n\\n使用`@Reusable`装饰器时，表示该自定义组件可以复用。与`@Component`结合使用，标记为`@Reusable`的自定义组件在从组件树\\n\\n中移除时，组件及其对应的JS对象将被放入复用缓存中。后续创建新自定义组件节点时，将复用缓存中的节点，从而节约组件重新\\n\\n创建的时间。\\n\\n![image-20250623200408525](assets/image-20250623200408525.png)\\n\\n1. 标记了`@Reusable`的自定义组件`listItem`列表项，在滑动出屏幕一定范围后，从组件树上被移除，组件的对象实例被放入CustomNode虚拟结点（与自定义组件一一对应的自定义结点）。\\n2. 在不断滑动过程中，列表的`RecycleManager`将这些`CustomNode`虚拟结点回收，根据复用标识[reuseId](https://developer.huawei.com/consumer/cn/doc/harmonyos-references/ts-universal-attributes-reuse-id)分组，形成`CachedRecycleNodes`的集合，即视图对象的复用缓存池。\\n3. 继续滑动，新的`listItem`需要在列表上显示时，`RecycleManager`优先从复用缓存池（`CachedRecycleNodes`集合）中查找对应`reuseId`的视图对象，然后将新的数据绑定到该视图，重用该节点并添加到组件树上。\\n\\n## 适用场景\\n\\n常见的组件复用开发场景是长列表滑动：在应用展示大量数据的列表界面中，当用户快速地进行滑动操作，列表项反复创建销毁可能导致卡顿等性能问题。这种情况下，使用组件复用机制可以重用已经创建过的列表项视图，提高滑动的流畅度。\\n\\n\\n\\n## 基本使用\\n\\n对于要复用的组件核心是要使用 `@Reusable` 装饰器 和 **reuseId**\\n\\n- `@Reusable`  用来定义可复用的组件\\n-  **reuseId** 表示该组件属于哪一类，因为可以可以复用好很多不同的组件\\n\\n### 定义要复用的组件  `Child`\\n\\n```typescript\\n@Component\\nstruct Child {\\n  @State message: string = \'child\';\\n\\n  build() {\\n    Column() {\\n      Text(this.message)\\n        .fontSize(30)\\n    }\\n    .borderWidth(1)\\n    .height(100)\\n  }\\n}\\n```\\n\\n### 组件添加上复用装饰器 `@Reusable`\\n\\n```typescript\\n@Reusable\\n@Component\\nstruct Child {\\n// ...\\n}\\n```\\n\\n### 父组件使用\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  build() {\\n    Column() {\\n      // 如果只有一个复用的组件，可以不用设置reuseId。\\n      Child()\\n        .reuseId(\'Child\')\\n    }\\n  }\\n}\\n```\\n\\n### 效果\\n\\n![image-20250623204001620](assets/image-20250623204001620.png)\\n\\n\\n\\n\\n\\n## 子组件属性更新\\n\\n很多时候，我们要复用的自己，往往是伴随着属性更新的，比如长列表中的联系人列表，结构可能一样，但是内容是不一样。\\n\\n要实现复用在组件更新，需要搭配组件的声明周期  `aboutToReuse`\\n\\n这里模拟长列表中反复切换显示子组件\\n\\n> 当一个可复用的自定义组件从复用缓存中重新加入到节点树时，触发aboutToReuse生命周期回调，并将组件的构造参数传递\\n>\\n> 给aboutToReuse。\\n\\n### 父组件控制子组件的显示和属性变更\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  @State\\n  num: number = 1\\n  @State\\n  isShow: boolean = false\\n\\n  build() {\\n    Column() {\\n      Button(\\"+\\")\\n        .onClick(() => {\\n          this.isShow = !this.isShow\\n        })\\n      if (this.isShow) {\\n        // 如果只有一个复用的组件，可以不用设置reuseId。\\n        Child({ message: \'child\' + ++this.num })\\n          .reuseId(\'Child\')\\n      }\\n    }\\n  }\\n}\\n```\\n\\n### 子组件使用 aboutToReuse 生命周期 更新属性\\n\\n> params 表示接收父组件传递的属性，对应父组件传递给子组件的 `{ message: \'child\' + ++this.num }`\\n\\n```typescript\\n  aboutToReuse(params: Record<string, string>) { \\n    this.message = params.message\\n  }\\n```\\n\\n### 效果\\n\\n![PixPin_2025-06-23_21-08-37](assets/PixPin_2025-06-23_21-08-37.gif)\\n\\n\\n\\n## 限制条件\\n\\n1. @Reusable装饰器仅用于自定义组件。\\n2. ComponentContent不支持传入@Reusable装饰器装饰的自定义组件。\\n3. @Reusable装饰器不建议嵌套使用，会增加内存，降低复用效率，加大维护难度。\\n4. 避免对@Link/@ObjectLink/@Prop等自动更新的状态变量，在aboutToReuse中重复更新。最佳实践请参考[组件复用最佳实践-优化状态管理，精准控制组件刷新范围使用](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-component-reuse#section4470171391314)。\\n5. 在滑动场景中，使用组件复用通常需要用该回调函数去更新组件的状态变量，因此在该回调函数中应避免耗时操作，否则会导致丢帧卡顿。最佳实践请参考[主线程耗时操作优化指导-组件复用回调](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-time-optimization-of-the-main-thread#section20815336174316)。\\n\\n\\n\\n\\n\\n## 其他搭配场景\\n\\n[链接](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/arkts-reusable#%E4%BD%BF%E7%94%A8%E5%9C%BA%E6%99%AF)\\n\\n![image-20250623211938406](assets/image-20250623211938406.png)\\n\\n## 关于我们\\n\\n[关于青蓝逐码组织](https://link.juejin.cn/?target=https%3A%2F%2Fwww.qinglanzhuma.cn%2F)\\n\\n如果你兴趣想要了解更多的鸿**蒙应用开发细节和最新资讯**，**甚至你想要做出一款属于自己的应用**！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n![image-20250622200325374](assets/image-20250622200325374.png)"}'),k={name:"鸿蒙开发技巧/HarmonyOS 组件复用 @Reusable装饰器的基本使用/HarmonyOS 组件复用 @Reusable装饰器的基本使用.md"};function d(o,s,c,E,u,b){return n(),i("div",null,[...s[0]||(s[0]=[e("",43)])])}const y=a(k,[["render",d]]);export{m as __pageData,y as default};
